import logging
import re
from datetime import datetime


class SWDLParser:
    POINT_TO_EXTRACT = [
        'SW build download started',
        'SW build download result: success',
        'SW build activation started',
        'SW build activation result: success'
    ]

    def __init__(self, file_path):
        """
        Constructor of SWDLParser class.
        :param file_path: path to the file to parse (SWDL report file)
        """
        self.file_path = file_path
        self.results = {}
        self._regex = re.compile(r'(?P<KEY>{}) (?P<VALUE>.+)'.format('|'.join(SWDLParser.POINT_TO_EXTRACT)))

    def parse(self):
        for line in self._read_file():
            match = self._regex.search(line)
            if match:
                logging.debug("Matched line: {}".format(line))
                phrase = match.group('KEY')
                key = phrase.split(': ')[0]
                value = match.group('VALUE')
                date_obj_value = datetime.strptime(value, '%a %b %d %H:%M:%S %Y')
                self.results[key] = date_obj_value

        return self.results

    def _read_file(self):
        with open(self.file_path, 'r') as file:
            for line in file:
                yield line
